def compute(vars):
    payment_2017 = vars["v1"]
    payment_2018 = vars["v2"]
    payment_2019 = vars["v3"]
    total_payments = payment_2017 + payment_2018 + payment_2019

    return {
        "value": total_payments,
        "trace": {
            "payment_2017": payment_2017,
            "payment_2018": payment_2018,
            "payment_2019": payment_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
